`timescale 1ns/1ps
module tb_v2_loop_transactions;
 logic clk=0,rst_n=0,abort=0,boundary=0,cv=0,wrv=0,rd=0,run_s=0; logic [2:0] cop=0,ct=0,wt=0,rt=0; logic [3:0] ws=0,ri=0; logic [95:0] wd=0; logic wrdy,crdy,done,rv,rsv; logic [95:0] rdata; logic ab,sb,cp,ack,busy,av; logic [29:0] counts; logic [5:0] ov; logic [95:0] sched_data; logic sv,sr=0,se,sl; logic [2:0] str; logic [3:0] si; logic [6:0] tick=0; always #5 clk=~clk;
 v2_loop_event_store store(.clk,.rst_n,.abort,.loop_boundary(boundary),.ctrl_valid(cv),.ctrl_ready(crdy),.ctrl_op(cop),.ctrl_track(ct),.ctrl_done(done),.write_valid(wrv),.write_ready(wrdy),.write_track(wt),.write_slot(ws),.write_data(wd),.read_enable(se),.read_track(str),.read_index(si),.read_valid(rv),.read_slot_valid(rsv),.read_data(rdata),.active_bank(ab),.shadow_bank(sb),.commit_pending(cp),.commit_ack(ack),.busy,.record_count(counts),.overflow(ov),.active_valid(av));
 v2_loop_scheduler sched(.clk,.rst_n,.run(run_s),.stop(1'b0),.flush(1'b0),.selected_track(3'd0),.loop_tick(tick),.read_valid(rv),.read_slot_valid(rsv),.read_data(rdata),.read_enable(se),.read_track(str),.read_index(si),.event_valid(sv),.event_ready(sr),.event_data(sched_data),.fault_valid(sl),.loop_boundary());
 task cmd(input [2:0] op); begin @(negedge clk);cop=op;cv=1;@(posedge clk);#1;cv=0;end endtask
 task put(input [2:0] tr,input [3:0] slot,input [95:0] d); begin @(negedge clk);wt=tr;ws=slot;wd=d;wrv=1;#1;if(!wrdy)$fatal(1,"write blocked");@(posedge clk);#1;wrv=0;end endtask
 initial begin repeat(2)@(posedge clk);rst_n=1;cmd(3'd5);repeat(100)@(posedge clk);put(0,0,96'h080000000000000000000001);put(5,0,96'h200000000000000000000055);cmd(3'd3);if(!cp)$fatal(1,"commit pending");boundary=1;@(posedge clk);#1;boundary=0;if(!ack||!av)$fatal(1,"boundary commit");run_s=1;repeat(250) begin @(posedge clk);#1;end;if(!sv||sched_data[94:91]!==4'd1)$fatal(1,"scheduler did not hold NOTE_ON");sr=1;@(posedge clk);#1;if(sv)$fatal(1,"scheduler did not handshake");run_s=0;cmd(3'd5);repeat(100)@(posedge clk);put(2,0,96'h200000000000000000000002);cmd(3'd3);abort=1;@(posedge clk);#1;abort=0;if(av!==1'b1)$fatal(1,"abort damaged active");$display("tb_v2_loop_transactions PASS");$finish;end
endmodule

